begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_catalog;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values
 ('00000000-0000-0000-0000-000000000161','life-owner@example.invalid','{"requested_username":"LifeOwner"}'),
 ('00000000-0000-0000-0000-000000000162','life-friend@example.invalid','{"requested_username":"LifeFriend"}');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000161","role":"authenticated"}',true);
select public.save_bracket_draft('10000000-0000-0000-0000-000000000161',0,'Manual lifecycle','','everything-else','crown','private','{"mode":"manual"}',array['Alpha','Beta','Gamma']);
select public.save_bracket_draft('10000000-0000-0000-0000-000000000162',0,'Timed lifecycle','','food-drink','donut','public','{"mode":"per-round","roundMinutes":[60,120]}',array['Cookies','Donuts','Popcorn']);
select public.save_bracket_draft('10000000-0000-0000-0000-000000000163',0,'','','everything-else','crown','private','{"mode":"manual"}',array['','']);
select throws_ok($$select public.submit_bracket('10000000-0000-0000-0000-000000000163',1)$$,'22023',null,'incomplete drafts cannot enter review');
select throws_ok($$select public.submit_bracket('10000000-0000-0000-0000-000000000161',9)$$,'40001',null,'stale draft submission cannot overwrite changes');
select lives_ok($$select public.submit_bracket('10000000-0000-0000-0000-000000000161',1)$$,'valid bracket enters review');
select public.submit_bracket('10000000-0000-0000-0000-000000000162',1);
select is((select status from public.brackets where id='10000000-0000-0000-0000-000000000161'),'pending_review','submission is pending, not live');
select ok((select started_at is null from public.brackets where id='10000000-0000-0000-0000-000000000161'),'pending review does not start the clock');
create temp table queued_time as select not_before from app_private.bracket_review_queue where bracket_id='10000000-0000-0000-0000-000000000161';
select public.submit_bracket('10000000-0000-0000-0000-000000000161',1);
select is((select not_before from app_private.bracket_review_queue where bracket_id='10000000-0000-0000-0000-000000000161'),(select not_before from queued_time),'submission retries do not restart review');
select ok((select not_before>clock_timestamp()+interval '2 minutes' from queued_time),'activation delay is enforced by server time');
select throws_ok($$update public.bracket_entries set name='Changed' where bracket_id='10000000-0000-0000-0000-000000000161'$$,'55000',null,'submitted entrants are frozen');
select ok(not has_function_privilege('authenticated','app_private.process_competitions()','execute'),'users cannot run the worker');
select ok(not has_table_privilege('authenticated','app_private.bracket_review_queue','update'),'users cannot accelerate their review');
select ok(not has_function_privilege('anon','public.cast_bracket_vote(uuid,uuid,bigint,uuid)','execute'),'anonymous voting is unavailable');
select ok(not has_table_privilege('authenticated','public.saved_brackets','insert'),'bookmark writes require the controlled operation');
select set_config('request.jwt.claims','{}',true);
select is(public.get_competition('10000000-0000-0000-0000-000000000162'),null::jsonb,'public submissions stay private while pending');
select app_private.process_competitions();
select is((select status from public.brackets where id='10000000-0000-0000-0000-000000000161'),'pending_review','the worker cannot activate early');
update app_private.bracket_review_queue set not_before=clock_timestamp()-interval '1 second';
select app_private.process_competitions();
select is((select status from public.brackets where id='10000000-0000-0000-0000-000000000161'),'active','a due submission goes live automatically');
select is((select count(*) from public.bracket_rounds where bracket_id='10000000-0000-0000-0000-000000000161'),2::bigint,'three entrants create two rounds');
select is((select count(*) from public.bracket_matchups where bracket_id='10000000-0000-0000-0000-000000000161' and round_index=0 and (left_entry_id is null or right_entry_id is null)),1::bigint,'a non-power-of-two bracket gets a seeded bye');
select is((select r.ends_at-b.started_at from public.brackets b join public.bracket_rounds r on r.bracket_id=b.id and r.round_index=0 where b.id='10000000-0000-0000-0000-000000000162'),interval '1 hour','duration clocks begin at actual activation');
select is((select jsonb_array_length(public.get_competition('10000000-0000-0000-0000-000000000162')->'matchups')),3,'public live bracket has a durable public snapshot');
select is(public.get_competition('10000000-0000-0000-0000-000000000161'),null::jsonb,'private live bracket is hidden from visitors');
create temp table life_match as select id,left_entry_id,right_entry_id from public.bracket_matchups where bracket_id='10000000-0000-0000-0000-000000000161' and round_index=0 and left_entry_id is not null and right_entry_id is not null;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000162","role":"authenticated"}',true);
select throws_ok($$select public.cast_bracket_vote((select id from life_match),(select left_entry_id from life_match),0,gen_random_uuid())$$,'42501',null,'outsiders cannot vote in private brackets');
select public.save_competition('10000000-0000-0000-0000-000000000162',true);
select public.save_competition('10000000-0000-0000-0000-000000000162',true);
select is((select count(*) from public.saved_brackets where user_id='00000000-0000-0000-0000-000000000162'),1::bigint,'bookmark retries do not duplicate saves');
select throws_ok($$select public.delete_competition('10000000-0000-0000-0000-000000000162')$$,'42501',null,'nonowners cannot delete a bracket');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000161","role":"authenticated"}',true);
select is(public.cast_bracket_vote((select id from life_match),(select left_entry_id from life_match),0,'40000000-0000-0000-0000-000000000161'),1::bigint,'first vote is stored authoritatively');
select is(public.cast_bracket_vote((select id from life_match),(select left_entry_id from life_match),0,'40000000-0000-0000-0000-000000000161'),1::bigint,'identical vote retries are idempotent');
select throws_ok($$select public.cast_bracket_vote((select id from life_match),(select right_entry_id from life_match),0,gen_random_uuid())$$,'40001',null,'stale replacements cannot overwrite a newer vote');
select is(public.cast_bracket_vote((select id from life_match),(select right_entry_id from life_match),1,gen_random_uuid()),2::bigint,'changing a vote replaces the original ballot');
select is((select count(*) from app_private.bracket_ballots where bracket_id='10000000-0000-0000-0000-000000000161'),1::bigint,'vote changes preserve one ballot per matchup/user');
select ok((select bool_and(m->>'leftVotes' is null and m->>'rightVotes' is null) from jsonb_array_elements(public.get_competition('10000000-0000-0000-0000-000000000161')->'matchups') m),'open snapshots do not expose totals');
select throws_ok($$select public.close_manual_round('10000000-0000-0000-0000-000000000162',0)$$,'42501',null,'public timed rounds cannot be manually closed');
select public.close_manual_round('10000000-0000-0000-0000-000000000161',0);
select is((select count(*) from app_private.bracket_ballots where bracket_id='10000000-0000-0000-0000-000000000161'),0::bigint,'closure atomically purges personal ballots');
select is((select count(*) from public.bracket_match_results where bracket_id='10000000-0000-0000-0000-000000000161'),2::bigint,'bye and majority outcomes are retained');
select public.close_manual_round('10000000-0000-0000-0000-000000000161',0);
select is((select current_round::integer from public.brackets where id='10000000-0000-0000-0000-000000000161'),1,'closure retries do not advance the next round');
-- Two real users split a timed matchup. The worker must persist one tie draw,
-- reject late replacements, and keep going while its creator is deactivated.
create temp table timed_match as select id,left_entry_id,right_entry_id from public.bracket_matchups where bracket_id='10000000-0000-0000-0000-000000000162' and round_index=0 and left_entry_id is not null and right_entry_id is not null;
select public.cast_bracket_vote((select id from timed_match),(select left_entry_id from timed_match),0,gen_random_uuid());
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000162","role":"authenticated"}',true);
select public.cast_bracket_vote((select id from timed_match),(select right_entry_id from timed_match),0,gen_random_uuid());
select is((select sum(vote_count)::bigint from app_private.bracket_vote_activity where bracket_id='10000000-0000-0000-0000-000000000162'),2::bigint,'first public ballots feed anonymous activity counters');
-- Advance fixture time without adding an application backdoor for schedule edits.
alter table public.bracket_rounds disable trigger guard_round_structure;
update public.bracket_rounds set ends_at=clock_timestamp()+interval '100 milliseconds' where bracket_id='10000000-0000-0000-0000-000000000162' and round_index=0;
alter table public.bracket_rounds enable trigger guard_round_structure;
select pg_sleep(.12);
select throws_ok($$select public.cast_bracket_vote((select id from timed_match),(select left_entry_id from timed_match),1,gen_random_uuid())$$,'55000',null,'late vote changes are rejected using server time');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000161","role":"authenticated"}',true);
select public.save_competition('10000000-0000-0000-0000-000000000162',true);
select public.deactivate_account();
select ok((select deactivated_at is not null from public.profiles where id='00000000-0000-0000-0000-000000000161'),'account deactivation is recorded');
select is((select count(*) from public.brackets where owner_id='00000000-0000-0000-0000-000000000161'),3::bigint,'deactivation retains live brackets and drafts');
select throws_ok($$select public.close_manual_round('10000000-0000-0000-0000-000000000161',1)$$,'42501',null,'private manual rounds wait while the owner is inactive');
select set_config('request.jwt.claims','{}',true);
select app_private.process_competitions();
select is((select current_round::integer from public.brackets where id='10000000-0000-0000-0000-000000000162'),1,'timed brackets progress while the owner is inactive');
select is((select resolution from public.bracket_match_results where matchup_id=(select id from timed_match)),'random_tie','positive ties use the saved server random draw');
create temp table tied_winner as select winner_entry_id from public.bracket_match_results where matchup_id=(select id from timed_match);
select app_private.process_competitions();
select is((select winner_entry_id from public.bracket_match_results where matchup_id=(select id from timed_match)),(select winner_entry_id from tied_winner),'worker retries cannot reroll a tie');
select is((select sum(vote_count)::bigint from app_private.bracket_vote_activity where bracket_id='10000000-0000-0000-0000-000000000162'),2::bigint,'trending participation survives timed ballot cleanup');
select is((select current_round::integer from public.brackets where id='10000000-0000-0000-0000-000000000161'),1,'private manual brackets wait for their inactive owner');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000161","role":"authenticated"}',true);
select throws_ok($$select public.reactivate_account()$$,'42501',null,'a revoked token cannot reactivate an account');
insert into auth.sessions(id,user_id,created_at,updated_at) values('50000000-0000-0000-0000-000000000161','00000000-0000-0000-0000-000000000161',now(),now());
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000161","role":"authenticated","session_id":"50000000-0000-0000-0000-000000000161"}',true);
select public.reactivate_account();
select ok((select deactivated_at is null from public.profiles where id='00000000-0000-0000-0000-000000000161'),'a fresh sign-in can reactivate the account');
select is((select count(*) from public.saved_brackets where user_id='00000000-0000-0000-0000-000000000161'),1::bigint,'reactivation retains the creator’s saved list');
select is((select display_name from public.profiles where id='00000000-0000-0000-0000-000000000161'),'LifeOwner','reactivation keeps the username');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000161","role":"authenticated"}',true);
select throws_ok($$select public.save_competition('10000000-0000-0000-0000-000000000162',true)$$,'42501',null,'old revoked sessions stay fenced after reactivation');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000161","role":"authenticated","session_id":"50000000-0000-0000-0000-000000000161"}',true);
select public.close_manual_round('10000000-0000-0000-0000-000000000161',1);
select is((select status from public.brackets where id='10000000-0000-0000-0000-000000000161'),'completed','returning owner can finish their manual bracket');
select is((select e.seed::integer from public.brackets b join public.bracket_entries e on e.id=b.champion_entry_id where b.id='10000000-0000-0000-0000-000000000161'),1,'zero-zero final advances the higher seed');
select lives_ok($$select public.delete_competition('10000000-0000-0000-0000-000000000161')$$,'whole-bracket deletion removes locked final results');
select is((select count(*) from public.bracket_entries where bracket_id='10000000-0000-0000-0000-000000000161'),0::bigint,'deleted competitors cascade');
select is((select count(*) from public.bracket_match_results where bracket_id='10000000-0000-0000-0000-000000000161'),0::bigint,'deleted finalized results cascade');
select is((select count(*) from app_private.deleting_brackets),0::bigint,'deletion bypass markers do not survive the transaction');
select public.delete_competition('10000000-0000-0000-0000-000000000162');
select is((select count(*) from public.saved_brackets where user_id='00000000-0000-0000-0000-000000000162' and bracket_id is null),1::bigint,'saved lists retain only an unavailable marker after bracket deletion');
select is((select count(*) from app_private.bracket_review_queue where bracket_id='10000000-0000-0000-0000-000000000162'),0::bigint,'review queue data cascades');
select is(public.get_competition('10000000-0000-0000-0000-000000000162'),null::jsonb,'deleted shared links return no bracket data');
select is((select count(*) from app_private.competition_worker_errors),0::bigint,'lifecycle processing leaves no worker errors');
select public.save_bracket_draft('10000000-0000-0000-0000-000000000163',1,'Pending deletion','','everything-else','crown','private','{"mode":"manual"}',array['One','Two']);
select public.submit_bracket('10000000-0000-0000-0000-000000000163',2);
select is((select count(*) from app_private.bracket_review_queue where bracket_id='10000000-0000-0000-0000-000000000163'),1::bigint,'a submitted bracket has a real queued review');
select public.delete_competition('10000000-0000-0000-0000-000000000163');
select is((select count(*) from app_private.bracket_review_queue where bracket_id='10000000-0000-0000-0000-000000000163'),0::bigint,'deleting a pending bracket cancels its queued activation');
select * from finish();
rollback;
